fn bump(v: (u32, u32, u32), change: &str) -> (u32, u32, u32) {
    match change {
        "fix" => (v.0, v.1, v.2 + 1),
        "feature" => (v.0, v.1 + 1, 0),
        "breaking" => (v.0 + 1, 0, 0),
        _ => v,
    }
}

fn main() {
    let mut v = (1, 4, 2);
    for change in ["fix", "feature", "fix", "breaking", "feature"] {
        v = bump(v, change);
        println!("{change} {}.{}.{}", v.0, v.1, v.2);
    }
}

