// The rule behind "^1.2": same major number, and at least 1.2.0.
fn caret_allows(req: (u32, u32), v: (u32, u32, u32)) -> bool {
    v.0 == req.0 && (v.1, v.2) >= (req.1, 0)
}

fn main() {
    let shelf = [(1, 1, 9), (1, 2, 0), (1, 2, 7), (1, 9, 3), (2, 0, 0)];
    for v in shelf {
        let ok = if caret_allows((1, 2), v) { "yes" } else { "no" };
        println!("{}.{}.{} {ok}", v.0, v.1, v.2);
    }
}

