use std::fs;
use std::path::PathBuf;
use std::sync::Barrier;

// Only here to make the unlucky timing happen on every run.
static BOTH_HERE: Barrier = Barrier::new(2);

/// A fixture: a fresh, empty file that belongs to one test.
fn fresh_file(test: &str) -> PathBuf {
    let path = std::env::temp_dir().join(format!("readers-{test}.txt"));
    fs::write(&path, "").unwrap();
    path
}

#[test]
fn saves_a_reader() {
    let file = fresh_file("saves_a_reader");
    fs::write(&file, "Ada").unwrap();
    BOTH_HERE.wait();
    BOTH_HERE.wait();
    let saved = fs::read_to_string(&file).unwrap();
    assert_eq!(saved, "Ada");
}

#[test]
fn clears_the_list() {
