//! Overdue fees for Mabel's library.

const DAILY: u32 = 25;

/// The fee in cents for a book returned `days_late` days late.
/// The first day is free, then 25 cents a day, never more than 500.
///
/// ```
/// assert_eq!(overdue::fee(3), 50);
/// ```
pub fn fee(days_late: u32) -> u32 {
    let charged = days_late.saturating_sub(1);
    capped(charged * DAILY)
}

fn capped(cents: u32) -> u32 {
    cents.min(500)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn first_day_is_free() {
        assert_eq!(fee(1), 0);
    }

    #[test]
    fn cap_is_five_dollars() {
        assert_eq!(capped(9000), 500);
    }
}

